mapper.select:
select

from fina_survey_price a
where  a.delete_flag = 0

    and a.area_categories_id = #{areaCategoriesId,jdbcType=BIGINT}


    and a.task_id = #{taskId,jdbcType=BIGINT}


    and a.task_info_content_id = #{taskInfoContentId,jdbcType=BIGINT}


    and a.direction_result_type_id = #{directionResultTypeId,jdbcType=BIGINT}

limit 1;
